const role=()=>me.prole==='owner'&&viewAs&&ROLES[viewAs]?viewAs:(ROLES[me.prole]?me.prole:'support');
const RC=k=>{const b=ROLES[k],c=(P().roleCfg||{})[k];return c&&k!=='owner'?{...b,...c}:b};const R=()=>RC(role());const canPage=p=>p==='search'||R().pages==='*'||R().pages.includes(p);
const fmtMob=m=>m?m.slice(0,5)+' '+m.slice(5):'—';
const maskM=m=>R().contacts?fmtMob(m):m?'<span class="mask">'+m.slice(0,2)+'••• ••'+m.slice(-3)+'</span>':'—';
const I={globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/>',image:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="10" r="2"/><path d="m21 16-5-5-9 9"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/>',card:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M6 15h4"/>',repeat:'<path d="M17 2l4 4-4 4"/><path d="M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4"/><path d="M21 13v2a3 3 0 0 1-3 3H3"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',store:'<path d="M4 9l1.5-5h13L20 9"/><path d="M4 9h16v11H4z"/><path d="M9 20v-6h6v6"/>',cal:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 3v4M16 3v4M3 10h18"/>',key:'<circle cx="8" cy="15" r="4"/><path d="M11 12l9-9M17 6l3 3"/>',users:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><path d="M16 4.5a3.5 3.5 0 0 1 0 7M18 14.5c2 .8 3.5 2.8 3.5 5.5"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M9 9h5a2 2 0 0 1 0 4h-4a2 2 0 0 0 0 4h5M12 6v2M12 16v2"/>',layers:'<path d="M12 3l9 5-9 5-9-5 9-5z"/><path d="M3 13l9 5 9-5"/>',mega:'<path d="M3 10v4l11 5V5L3 10z"/><path d="M14 8a4 4 0 0 1 0 8M7 15v4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6l8-3z"/>',sliders:'<path d="M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12"/><circle cx="16" cy="6" r="2"/><circle cx="10" cy="12" r="2"/><circle cx="18" cy="18" r="2"/>',x:'<path d="M6 6l12 12M18 6L6 18"/>',alert:'<path d="M12 3l9.5 17h-19L12 3z"/><path d="M12 10v4M12 17.5v.5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.5"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M4 16V6a2 2 0 0 1 2-2h10"/>',lock:'<rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',chat:'<path d="M4 5h16v11H9l-5 4V5z"/>',bell:'<path d="M6 16V11a6 6 0 0 1 12 0v5l2 2H4l2-2z"/><path d="M10 20a2 2 0 0 0 4 0"/>',tag:'<path d="M3 12V4h8l10 10-8 8L3 12z"/><circle cx="7.5" cy="7.5" r="1.5"/>',logout:'<path d="M15 4h4v16h-4M10 8l-4 4 4 4M6 12h10"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',phone:'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 18h2"/>'};
const xi=(k,s=18)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[k]||''}</svg>`;
const xp=(t,c)=>`<span class="pill ${c}">${esc(t)}</span>`;
const planTag=k=>`<span class="xplan ${k}">${esc(P().plans[k].name)}</span>`;
const stPill=s=>s==='active'?xp('Active','good'):s==='suspended'?xp('Suspended','bad'):s==='completed'?xp('Completed','info'):s==='draft'?xp('Draft','mute'):s==='archived'?xp('Archived','mute'):xp(s,'mute');
const liveTag=a=>a&&a.live?'<span class="xlive">Live</span>':'';
const csv=rows=>rows.map(r=>r.map(c=>{const s=String(c??'');return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(',')).join('\n');

/* ---------- numbers ---------- */
function metrics(){const t=dk(NOWD()),d7=dk(addD(NOWD(),-6)),d30=dk(addD(NOWD(),-29));
  const act=from=>D.users.filter(u=>u.days.some(x=>x>=from&&x<=t)).length;
  const dau=[];for(let i=59;i>=0;i--){const k=dk(addD(NOWD(),-i));dau.push([k,D.users.filter(u=>u.days.includes(k)).length])}
  const mStart=dk(new Date(NOWD().getFullYear(),NOWD().getMonth(),1)),lStart=dk(new Date(NOWD().getFullYear(),NOWD().getMonth()-1,1));
  const weeks=[];for(let w=11;w>=0;w--){const to=addD(NOWD(),-w*7),from=addD(to,-6);weeks.push([df(from).slice(0,6),D.accounts.filter(a=>a.signup>=dk(from)&&a.signup<=dk(to)).length])}
  const paid=D.buys.filter(b=>b.status==='Paid'&&b.amount>0);const months=[];for(let m=5;m>=0;m--){const s=new Date(NOWD().getFullYear(),NOWD().getMonth()-m,1),e=new Date(NOWD().getFullYear(),NOWD().getMonth()-m+1,1);months.push([s.toLocaleDateString('en-IN',{month:'short'}),paid.filter(b=>b.date>=dk(s)&&b.date<dk(e)).reduce((x,b)=>x+b.amount,0)])}
  const active=D.accounts.filter(a=>status(a)==='active');
  return {dau:act(t),wau:act(d7),mau:act(d30),dauS:dau,accMonth:D.accounts.filter(a=>a.signup>=mStart).length,accLast:D.accounts.filter(a=>a.signup>=lStart&&a.signup<mStart).length,weeks,months,
    entries:D.events.reduce((s,e)=>s+e.entries.length,0),gmv:D.events.reduce((s,e)=>s+e.total,0),sold:paid.reduce((s,b)=>s+b.amount,0),used:D.accounts.reduce((s,a)=>s+a.used,0),unused:D.accounts.reduce((s,a)=>s+Math.max(0,bal(a)),0),
    live:D.events.filter(e=>e.status==='active'&&Math.abs((toD(e.date)-toD(t))/DAY)<=1).length,upcoming:D.events.filter(e=>e.status==='active'&&e.date>t&&e.date<=dk(addD(NOWD(),30))).length,
    mrr:active.reduce((s,a)=>{const p=P().plans[plan(a)];return s+(p.charge?+p.price:0)},0),mrrIf:active.reduce((s,a)=>s+(+P().plans[plan(a)].price||0),0),
    consented:GST.filter(g=>g.consent).length,converted:D.accounts.filter(a=>a.fromGuest!=null||a.source==='Saw it as a guest').length,
    funnel:[['Signed up',D.accounts.length],['Created an event',D.accounts.filter(a=>a.events.length).length],['Recorded a Moi',D.accounts.filter(a=>a.events.some(id=>EV[id].entries.length)).length],['Bought credits',D.accounts.filter(a=>D.buys.some(b=>b.acc===a.id&&b.status==='Paid'&&b.amount>0)).length]],
    openTk:P().tickets.filter(x=>x.status==='open').length}}

/* ---------- charts ---------- */
function niceStep(x){const p=Math.pow(10,Math.floor(Math.log10(Math.max(x,1)))),f=x/p;return (f<=1?1:f<=2?2:f<=5?5:10)*p}
function lineChart(series,{h=200,color='var(--x1)'}={}){const W=640,H=h,pl=36,pr=10,pt=12,pb=24,max=Math.max(1,...series.map(s=>s[1])),step=Math.max(1,niceStep(max/4)),top=step*Math.ceil(max/step);
  const x=i=>pl+(W-pl-pr)*i/(series.length-1),y=v=>pt+(H-pt-pb)*(1-v/top),pts=series.map((s,i)=>`${x(i).toFixed(1)},${y(s[1]).toFixed(1)}`).join(' ');
  const ticks=[];for(let v=0;v<=top;v+=step)ticks.push(v);const last=series[series.length-1];
  return `<svg class="xchart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily active users, last 60 days">${ticks.map(v=>`<line x1="${pl}" x2="${W-pr}" y1="${y(v)}" y2="${y(v)}" stroke="var(--xgrid)"/><text x="${pl-6}" y="${y(v)+4}" text-anchor="end">${num(v)}</text>`).join('')}<polygon points="${pl},${y(0)} ${pts} ${W-pr},${y(0)}" fill="${color}" fill-opacity=".12"/><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linejoin="round"/><circle cx="${x(series.length-1)}" cy="${y(last[1])}" r="4.5" fill="${color}"/>${series.map((s,i)=>i%10===0||i===series.length-1?`<text x="${x(i)}" y="${H-6}" text-anchor="${i===series.length-1?'end':'middle'}">${df(s[0]).slice(0,6)}</text>`:'').join('')}</svg>`}
function barChart(series,{h=190,color='var(--x1)',fmtY=num}={}){const W=640,H=h,pl=48,pr=8,pt=14,pb=24,max=Math.max(1,...series.map(s=>s[1])),step=Math.max(1,niceStep(max/4)),top=step*Math.ceil(max/step);
  const bw=(W-pl-pr)/series.length,y=v=>pt+(H-pt-pb)*(1-v/top),ticks=[];for(let v=0;v<=top;v+=step)ticks.push(v);
  return `<svg class="xchart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Bar chart">${ticks.map(v=>`<line x1="${pl}" x2="${W-pr}" y1="${y(v)}" y2="${y(v)}" stroke="var(--xgrid)"/><text x="${pl-6}" y="${y(v)+4}" text-anchor="end">${fmtY(v)}</text>`).join('')}${series.map((s,i)=>`<rect x="${pl+i*bw+bw*.18}" y="${y(s[1])}" width="${bw*.64}" height="${Math.max(0,y(0)-y(s[1]))}" rx="4" fill="${color}"><title>${esc(s[0])}: ${fmtY(s[1])}</title></rect><text x="${pl+i*bw+bw/2}" y="${H-6}" text-anchor="middle">${esc(s[0])}</text>`).join('')}</svg>`}
const hbars=(rows,fmtV=num,color='var(--x1)')=>{const m=Math.max(1,...rows.map(r=>r[1]));return `<div class="xhbars">${rows.map(r=>`<div class="xhb"><span title="${esc(r[0])}">${esc(r[0])}</span><div class="t"><i style="width:${(r[1]/m*100).toFixed(1)}%;background:${color}"></i></div><b>${fmtV(r[1])}</b></div>`).join('')}</div>`};
const countBy=(arr,f)=>{const o={};arr.forEach(x=>{const k=f(x);o[k]=(o[k]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1])};

/* ---------- table ---------- */
const TB={};
function table(key,cols,rows,{click,per=20}={}){const s=TB[key]=TB[key]||{sort:null,dir:-1,page:0};let r=rows;
  if(s.sort!=null){const c=cols[s.sort];r=[...rows].sort((a,b)=>{const x=c.v(a),y=c.v(b);return (x>y?1:x<y?-1:0)*s.dir})}
  const pages=Math.max(1,Math.ceil(r.length/per));if(s.page>=pages)s.page=pages-1;const sl=r.slice(s.page*per,s.page*per+per);
  return `<div class="xtw"><table><thead><tr>${cols.map((c,i)=>`<th class="${c.r?'r':''}" ${c.v?`aria-sort="${s.sort===i?(s.dir>0?'ascending':'descending'):'none'}"`:''}>${c.v?`<button data-mact="sort" data-t="${key}" data-i="${i}">${c.t}${s.sort===i?(s.dir>0?' ↑':' ↓'):''}</button>`:c.t}</th>`).join('')}</tr></thead>
  <tbody>${sl.length?sl.map(x=>`<tr ${click?`class="click" data-mact="${click}" data-id="${esc(x.id)}" tabindex="0"`:''}>${cols.map(c=>`<td class="${c.r?'r':''}">${c.h(x)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}"><div class="xempty">Nothing matches these filters.</div></td></tr>`}</tbody></table></div>
  <div class="xpager"><span>${r.length?`${s.page*per+1}–${Math.min(r.length,s.page*per+per)} of ${num(r.length)}`:'0 results'}</span><div class="btn-row"><button class="btn btn-ghost btn-sm" data-mact="pg" data-t="${key}" data-d="-1" ${s.page?'':'disabled'}>Previous</button><button class="btn btn-ghost btn-sm" data-mact="pg" data-t="${key}" data-d="1" ${s.page<pages-1?'':'disabled'}>Next</button></div></div>`}

/* ---------- menu ---------- */
const NAV=[['Business',[['overview','Overview','grid'],['accounts','Accounts','store'],['events','Events','cal'],['logins','Logins & users','key'],['payments','Online payments','card'],['support','Support inbox','chat']]],
  ['Growth',[['guests','Guest database','users'],['web','Website & leads','globe'],['campaigns','Campaigns','mega'],['announce','Announcements','bell'],['coupons','Offer codes','tag']]],
  ['Money',[['money','Money overview','coin'],['credits','Credit sales','tag'],['cplan','Message stock & planning','layers'],['subs','Subscriptions','repeat'],['plans','Plans & prices','layers']]],
  ['Control',[['activity','Activity log','clock'],['team','Admin team & access','shield'],['platform','Platform settings','sliders']]]];
function rail(page){const m={accounts:D.accounts.length,events:D.events.length,logins:D.users.length,guests:GST.length,support:P().tickets.filter(t=>t.status==='open').length,web:leadDueCount()};
  return `<aside class="xrail ${UI.menu?'open':''}" aria-label="Master admin menu"><div class="xbrand"><i>${mpMark()}</i><div><b>${MPW()}</b><em class="tagl">Grow Together</em><small>Master admin</small></div></div>
  <nav class="xnav">${NAV.map(([sec,items])=>{const vis=items.filter(([k])=>canPage(k));return vis.length?`<div class="xsec">${sec}</div>${vis.map(([k,l,i])=>`<a href="#admin-${k}" class="${page===k?'on':''}" ${page===k?'aria-current="page"':''}>${xi(i)}${l}${m[k]?`<span class="n ${k==='support'||k==='web'?'hot':''}">${num(m[k])}</span>`:''}</a>`).join('')}`:''}).join('')}</nav>
  <div class="xfoot"><div class="xme"><b>${esc(me.name)}</b><small>${ROLES[me.prole]?ROLES[me.prole].name:''}${viewAs&&me.prole==='owner'?' · viewing as '+R().name:''}</small></div>
  ${me.prole==='owner'?`<label for="mxViewAs">Check what a role sees</label><select id="mxViewAs"><option value="">Owner (you)</option>${Object.entries(ROLES).filter(([k])=>k!=='owner').map(([k,r])=>`<option value="${k}" ${viewAs===k?'selected':''}>${r.name}</option>`).join('')}</select>`:''}
  <button class="xlogout" data-mact="logout">${xi('logout',16)}Log out</button></div></aside>`}

/* ---------- pages ---------- */
const UI={menu:false,drawer:null};

/* ---------- date ranges (each page keeps its own) ---------- */
const RGS={ov:{k:'30',from:'',to:''},sr:{k:'all',from:'',to:''},tx:{k:'7',from:'',to:''},sb:{k:'all',from:'',to:''}};
function range(n){const r=RGS[n],t=dk(NOWD());if(r.k==='custom')return [r.from||'0000-01-01',r.to||'9999-12-31'];if(r.k==='all')return ['0000-01-01','9999-12-31'];const d={today:0,'2':1,'7':6,'30':29,'90':89}[r.k];return [dk(addD(NOWD(),-d)),t]}
const inR=(n,d)=>{if(!d)return false;const [f,t]=range(n),k=String(typeof d==='number'?dk(new Date(d)):d).slice(0,10);return k>=f&&k<=t};
const rangeTxt=n=>{const r=RGS[n];if(r.k==='all')return 'All time';const [f,t]=range(n);return f===t?df(f):`${df(f)} – ${df(t)}`};
function rangeBar(n){const r=RGS[n];return `<div class="xrange" role="group" aria-label="Date range">${xi('cal',16)}${[['today','Today'],['2','2 days'],['7','7 days'],['30','1 month'],['90','3 months'],['all','All time'],['custom','Custom']].map(([k,l])=>`<button class="chip ${r.k===k?'on':''}" data-mact="rg" data-st="${n}" data-v="${k}">${l}</button>`).join('')}${r.k==='custom'?`<input type="date" id="rg_${n}_from" value="${esc(r.from)}" aria-label="From date"><span class="muted small">to</span><input type="date" id="rg_${n}_to" value="${esc(r.to)}" aria-label="To date">`:''}</div>`}

/* ---------- every Moi entry as a row (live entries from the app, sample entries generated) ---------- */
const moiCode=(e,i)=>`${e.no||e.id}/${String(i+1).padStart(3,'0')}`;
function entryRows(e){return e.entries.map((x,i)=>{const g=GI[x[0]]||{},m=x[5];
  if(m){const f=feeOf(m);return {id:m.code,code:m.code,eid:e.id,acc:e.acc,gid:x[0],name:m.c.name,mobile:m.c.mobile||'',consent:!!m.c.consent,place:m.c.place||'',rel:m.c.relationship||'',amt:+m.amount||0,item:isItem(m)?amtTxt(m):'',mode:m.mode,fee:f.fee,net:f.net,paid:f.paid,by:f.by,status:m.status,date:m.date,who:uname(m.collected_by),live:true}}
  const amt=x[1],on=x[2]==='online',fee=on?Math.round(amt*2/100*1.18*100)/100:0,guestPays=on&&i%5===0;
  return {id:moiCode(e,i),code:moiCode(e,i),eid:e.id,acc:e.acc,gid:x[0],name:g.name||'Guest',mobile:g.mobile||'',consent:!!g.consent,place:g.city||'',rel:RELS[x[3]]||'',amt,item:x[4]!=='cash'?x[4]:'',mode:x[2],fee,net:guestPays?amt:Math.round((amt-fee)*100)/100,paid:guestPays?Math.round((amt+fee)*100)/100:amt,by:guestPays?'guest':'family',status:x[4]!=='cash'?'received':(x[2]==='upi'&&i%17===0?'pending':'received'),date:e.date,who:''}})}
const showMob=r=>R().contacts||r.consent?fmtMob(r.mobile):r.mobile?'<span class="mask">'+r.mobile.slice(0,2)+'••• ••'+r.mobile.slice(-3)+'</span>':'—';

/* ---------- plan periods ---------- */
const subOf=a=>a.live?a.ref.sub:(over(a).sub||a.sub);
function subSt(a){const s=subOf(a);if(!s)return 'active';const d=Math.round((toD(s.end)-toD(dk(NOWD())))/DAY);if(d<0)return planCharges()?'expired':'continuing';return d<=15&&planCharges()?'expiring':'active'}
const subPill=a=>{const s=subSt(a),sb=subOf(a)||{};return s==='expired'?xp('Locked · ended '+df(sb.end),'bad'):s==='expiring'?xp('Ends '+df(sb.end),'warn'):s==='continuing'?xp('Free year over · still free','mute'):xp((sb.period==='free'?'Free till ':'Paid till ')+df(sb.end),'good')};

/* ---------- global search ---------- */
let Q='';
const searchBar=()=>`<form class="xsearch" data-mform="gsearch" role="search">${xi('search',18)}<input type="search" id="mx_q" value="${esc(Q)}" placeholder="Search name, mobile, place, event no, receipt no, language…" aria-label="Search everything"><button class="btn btn-primary btn-sm">Search</button></form>`;
function pSearch(){const q=Q.trim().toLowerCase(),qd=q.replace(/\D/g,'');
  if(!q)return `<div class="xph"><div><h1>Search</h1><p class="sub">Type a customer name, mobile number, city or district, event number, receipt number, or a receipt language like Tamil.</p></div></div>${rangeBar('sr')}`;
  const has=v=>String(v||'').toLowerCase().includes(q),hasM=m=>qd.length>=4&&String(m||'').includes(qd);
  const accs=D.accounts.filter(a=>([a.id,a.name,a.owner,a.email,a.city,a.district,a.state,a.source,P().plans[plan(a)].name,a.kind].some(has)||hasM(a.mobile))&&inR('sr',a.signup));
  const evs=D.events.filter(e=>([e.id,e.no,e.name,e.type,e.venue,e.city,LNAME[e.lang],ACC[e.acc].name].some(has))&&inR('sr',e.date));
  const rec=[];if(/moi|[0-9]/i.test(q))for(const e of D.events){if(!inR('sr',e.date))continue;e.entries.forEach((x,i)=>{const code=x[5]?x[5].code:moiCode(e,i);if(code.toLowerCase().includes(q)&&rec.length<40)rec.push({code,e,i})})}
  const gs=GST.filter(g=>(has(g.name)||hasM(g.mobile)||has(g.city))&&(RGS.sr.k==='all'||inR('sr',g.last)));
  const us=D.users.filter(u=>has(u.name)||has(u.username)||hasM(u.mobile));
  const bs=R().money?D.buys.filter(b=>(has(b.id)||has(b.code)||has(b.kind))&&inR('sr',b.date)):[];
  const grp=(t,n,rows)=>`<section class="xpanel"><div class="xph2"><h2>${t} <span class="muted small">${num(n)}</span></h2></div>${n?rows:'<p class="small muted">No matches.</p>'}</section>`;
  const more=n=>n>12?`<p class="small muted">Showing 12 of ${num(n)}. Narrow the search or the dates.</p>`:'';
  return `<div class="xph"><div><h1>Results for “${esc(Q)}”</h1><p class="sub">${rangeTxt('sr')}</p></div></div>${rangeBar('sr')}
  ${grp('Accounts',accs.length,accs.slice(0,12).map(a=>`<button class="xrow" data-mact="acc" data-id="${a.id}"><b>${esc(a.name)}</b> ${liveTag(a)} ${planTag(plan(a))}<small>${a.id} · ${esc(a.owner)} · ${maskM(a.mobile)} · ${esc([a.city,a.district,a.state].filter(Boolean).join(', '))}</small></button>`).join('')+more(accs.length))}
  ${grp('Events',evs.length,evs.slice(0,12).map(e=>`<button class="xrow" data-mact="ev" data-id="${e.id}"><b>${esc(e.name)}</b> ${e.live?'<span class="xlive">Live</span>':''}<small>${esc(e.no||e.id)} · ${df(e.date)} · ${esc(e.venue)}, ${esc(e.city)} · ${LNAME[e.lang]||e.lang} receipts · ${esc(ACC[e.acc].name)}</small></button>`).join('')+more(evs.length))}
  ${grp('Receipts',rec.length,rec.slice(0,12).map(r=>`<button class="xrow" data-mact="ev" data-id="${r.e.id}" data-q="${esc(r.code)}"><b class="code">${esc(r.code)}</b><small>${esc(r.e.name)} · ${df(r.e.date)} · ${inr(r.e.entries[r.i][1])}</small></button>`).join('')+more(rec.length))}
  ${R().guests?grp('Guests',gs.length,gs.slice(0,12).map(g=>`<button class="xrow" data-mact="guest" data-id="${g.id}"><b>${esc(g.name)}</b> ${g.consent?xp('Agreed','good'):''}<small>${showMob(g)} · ${esc(g.city)} · ${num(g.events)} functions · ${inr(g.total)} given</small></button>`).join('')+more(gs.length)):''}
  ${grp('Logins',us.length,us.slice(0,12).map(u=>`<button class="xrow" data-mact="acc" data-id="${u.acc}"><b>${esc(u.name)}</b><small>${esc(u.role)} · ${esc(u.email||u.username)} · ${maskM(u.mobile)} · ${esc(ACC[u.acc].name)}</small></button>`).join('')+more(us.length))}
  ${R().money?grp('Payments',bs.length,bs.slice(0,12).map(b=>`<button class="xrow" data-mact="acc" data-id="${b.acc}"><b>${esc(b.id)}</b><small>${esc(ACC[b.acc].name)} · ${df(b.date)} · ${num(b.qty)} credits · ${b.amount?inr(b.amount):'Free'}</small></button>`).join('')+more(bs.length)):''}`}

/* ---------- guest profile ---------- */
function guestDrawer(id){const g=GI[id];if(!g)return '';const rows=[];D.events.forEach(e=>e.entries.forEach((x,i)=>{if(x[0]===id)rows.push({e,i,x})}));rows.sort((a,b)=>String(b.e.date).localeCompare(String(a.e.date)));
  return drawer(`${esc(g.name)}`,`${showMob(g)} · ${esc(g.city)} · ${LNAME[g.lang]||''}`,`
  <div class="xmini"><div><b>${num(g.events)}</b><span>Functions</span></div><div><b>${num(Object.keys(g.rel).length)}</b><span>Families</span></div><div><b>${short(g.total)}</b><span>Total given</span></div><div><b>${df(g.last)}</b><span>Last Moi</span></div></div>
  <section class="xpanel"><h3>Moi given</h3><div class="xtw"><table><thead><tr><th>Function</th><th>Receipt</th><th>Relation</th><th class="r">Amount</th></tr></thead><tbody>${rows.map(r=>`<tr class="click" data-mact="ev" data-id="${r.e.id}" tabindex="0"><td><b>${esc(r.e.name)}</b><small>${df(r.e.date)} · ${esc(ACC[r.e.acc].name)}</small></td><td class="code">${esc(r.x[5]?r.x[5].code:moiCode(r.e,r.i))}</td><td>${esc(r.x[5]?r.x[5].c.relationship:RELS[r.x[3]])}</td><td class="r">${r.x[4]!=='cash'?esc(r.x[4]):inr(r.x[1])}</td></tr>`).join('')}</tbody></table></div></section>`)}

/* ---------- online payments ---------- */
function txRows(){const out=[];D.events.forEach(e=>{entryRows(e).forEach(r=>{if(r.mode==='online'&&r.status!=='void'&&r.status!=='rejected')out.push({...r,ev:e})})});return out.sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function pPayments(){const all=txRows(),rows=all.filter(r=>inR('tx',r.date)),sum=k=>rows.reduce((s,r)=>s+(+r[k]||0),0);const gst=sum('fee')-sum('fee')/1.18,fam=rows.filter(r=>r.by==='family').reduce((s,r)=>s+r.fee,0);
  const days={};rows.forEach(r=>{days[r.date]=(days[r.date]||0)+r.amt});const ds=Object.entries(days).sort((a,b)=>a[0].localeCompare(b[0])).slice(-14).map(([d,v])=>[df(d).slice(0,6),v]);
  const cols=[{t:'Date',h:r=>df(r.date),v:r=>r.date},{t:'Receipt',h:r=>`<span class="code">${esc(r.code)}</span>${r.live?' <span class="xlive">Live</span>':''}`,v:r=>r.code},{t:'Event',h:r=>`<b>${esc(r.ev.name)}</b><small>${esc(ACC[r.acc].name)}</small>`,v:r=>r.ev.name},{t:'Guest',h:r=>R().guests?esc(r.name):'<span class="mask">Guest</span>'},{t:'Moi',h:r=>inr(r.amt),v:r=>r.amt,r:1},{t:'Fee',h:r=>inr2(r.fee)+`<small>${r.by==='guest'?'guest paid':'family paid'}</small>`,v:r=>r.fee,r:1},{t:'Guest paid',h:r=>inr2(r.paid),v:r=>r.paid,r:1},{t:'To family',h:r=>`<b>${inr2(r.net)}</b>`,v:r=>r.net,r:1}];
  return `<div class="xph"><div><h1>Online payments</h1><p class="sub">Every online Moi through the payment gateway: what guests paid, the gateway fee and what reached each family. ${rangeTxt('tx')}.</p></div><button class="btn btn-ghost" data-mact="csv" data-k="tx">${xi('copy',16)}Copy as CSV</button></div>${rangeBar('tx')}
  <div class="xkpis"><div class="xkpi xhero"><span class="lbl">Transactions</span><span class="v">${num(rows.length)}</span><span class="d">${inr(sum('paid'))} paid by guests</span></div><div class="xkpi"><span class="lbl">Gateway fees</span><span class="v">${inr2(sum('fee'))}</span><span class="d">incl. ${inr2(gst)} GST · ${inr2(fam)} paid by families</span></div><div class="xkpi"><span class="lbl">Reached families</span><span class="v">${short(sum('net'))}</span><span class="d">after fees</span></div><div class="xkpi"><span class="lbl">Average online Moi</span><span class="v">${inr(rows.length?sum('amt')/rows.length:0)}</span><span class="d">${num(new Set(rows.map(r=>r.eid)).size)} events</span></div></div>
  ${ds.length?`<section class="xpanel"><div class="xph2"><h2>Online Moi by day</h2></div>${barChart(ds,{color:'var(--x2)',fmtY:v=>short(v)})}</section>`:''}
  <section class="xpanel">${table('tx',cols,rows)}</section>`}
const inr2=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:Number(n)%1?2:0,maximumFractionDigits:2});

