  const cols=[{t:'Date',h:b=>df(b.date),v:b=>b.date},{t:'Account',h:b=>`<b>${esc(ACC[b.acc].name)}</b> ${liveTag(ACC[b.acc])}<small>${b.acc}</small>`,v:b=>ACC[b.acc].name},{t:'Payment',h:b=>`${esc(b.kind||b.id)}<small>${esc(b.method)}${b.code?' · code '+esc(b.code):''}${b.exp?' · valid till '+df(b.exp):''}</small>`},{t:'Credits',h:b=>num(b.qty),v:b=>b.qty,r:1},{t:'Amount',h:b=>b.amount?inr(b.amount):'Free',v:b=>b.amount,r:1},{t:'Status',h:b=>b.status==='Paid'?xp('Paid','good'):xp('Failed','bad'),v:b=>b.status}];
