 wsDel:b=>{const sec=b.dataset.sec,L=P().web[sec],x=L.find(y=>y.id===b.dataset.id);if(!x)return;P().web[sec]=L.filter(y=>y!==x);if(wf.ws&&wf.ws.id===x.id)wf.ws=null;alog('Website '+WS[sec].one+' deleted',x.title||x.name||x.q||'');save();toast('Deleted from the website');rr()},
